export function mountLanding(){
 release();const root=document.querySelector('#public-landing');if(!root)return;
 const controller=new AbortController(),signal=controller.signal,on=(el,type,fn,opts={})=>el?.addEventListener(type,fn,{...opts,signal});
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;try{paused=paused||sessionStorage.getItem('lexora.landingPaused')==='true';}catch{}
 const stopScene=mountWordScene(root,()=>paused||reduced.matches),motion=root.querySelector('#lx-motion');
 function motionLabel(){motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'Animatsiyani davom ettirish':'Animatsiyani to‘xtatish');motion.querySelector('span').textContent=paused?'Harakatni davom ettirish':'Harakatni to‘xtatish';root.classList.toggle('lx-paused',paused);}
 on(motion,'click',()=>{paused=!paused;try{sessionStorage.setItem('lexora.landingPaused',String(paused));}catch{}motionLabel();});motionLabel();
 on(root.querySelector('#lx-theme'),'click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('lexora.theme',theme);}catch{}});
 root.querySelectorAll('[data-landing-jump]').forEach(b=>on(b,'click',()=>document.getElementById(b.dataset.landingJump)?.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'})));
 let index=0,back=false;const flip=root.querySelector('#lx-demo-flip'),content=root.querySelector('#lx-demo-content');
 on(flip,'click',()=>{if(back){index=(index+1)%words.length;back=false;}else back=true;const [uz,en,example]=words[index];content.innerHTML=back?`<p>Inglizcha javob</p><h3>${en}</h3><p>${example}</p>`:`<p>Inglizchasini eslaysizmi?</p><h3>${uz}</h3><p>Avval o‘zingiz eslab ko‘ring.</p>`;flip.innerHTML=(back?'Keyingi so‘z ':'Javobni ochish ')+arrow;root.querySelector('#lx-demo-count').textContent=`0${index+1} / 03`;root.querySelector('#lx-demo-card').classList.toggle('lx-is-back',back);});
 const journey=root.querySelector('#lx-method'),stage=root.querySelector('.lx-journey-stage'),chapters=[...root.querySelectorAll('[data-chapter]')],previews=[...root.querySelectorAll('[data-preview]')];let active=-1,raf=0;
 function activate(n){if(active===n)return;active=n;stage.dataset.stage=n;chapters.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)));previews.forEach((p,i)=>{p.inert=i!==n;});root.querySelectorAll('.lx-stage-pagination i').forEach((d,i)=>d.classList.toggle('active',i===n));root.querySelector('#lx-stage-name').textContent=['Lug‘at mashqi','Speaking tahlili','Watch & learn'][n];}
 function sync(){raf=0;if(!root.isConnected){release();return;}if(innerWidth<760||reduced.matches)return;const rect=journey.getBoundingClientRect(),range=rect.height-innerHeight,progress=Math.max(0,Math.min(.999,-rect.top/Math.max(1,range)));activate(Math.min(2,Math.floor(progress*3)));journey.style.setProperty('--journey-progress',progress);}
 on(window,'scroll',()=>{if(!raf)raf=requestAnimationFrame(sync);},{passive:true});on(window,'resize',sync);
 chapters.forEach((b,n)=>on(b,'click',()=>{activate(n);if(innerWidth>=760&&!reduced.matches){const top=journey.getBoundingClientRect().top+scrollY,range=journey.offsetHeight-innerHeight;window.scrollTo({top:top+range*(n/3+.08),behavior:'smooth'});}}));activate(0);sync();
 root.querySelectorAll('[data-note]').forEach(b=>on(b,'click',()=>{root.querySelectorAll('[data-note]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));root.querySelector('#lx-explanation').innerHTML=b.dataset.note==='tend'?'<strong>tend to + fe’l</strong><p>Odatdagi harakat: “odatda … qilaman”.</p>':'<strong>try to + fe’l</strong><p>Biror ishni qilishga harakat: “ishlatishga harakat qilaman”.</p>';}));
 on(root.querySelector('#lx-save-word'),'click',()=>{root.querySelector('#lx-save-status').textContent='Namuna saqlandi. Shaxsiy iboralar uchun hisobingizga kiring.';root.querySelector('#lx-save-word').classList.add('lx-saved');});
 release=()=>{controller.abort();cancelAnimationFrame(raf);stopScene();};
}
